<template><el-form label-position="top" @submit.prevent="save"><el-alert v-if="error" :title="error" type="error"/><el-form-item label="事项标题"><el-input v-model="form.title" maxlength="200"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="主处理人"><el-select v-model="form.assignee" filterable><el-option v-for="u in candidateUsers" :key="u.id" :value="u.id" :label="u.full_name||u.username"/></el-select></el-form-item><el-form-item label="协办人"><el-select v-model="form.collaborators" multiple filterable><el-option v-for="u in candidates.users" :key="u.id" :value="u.id" :label="u.full_name||u.username"/></el-select></el-form-item><el-form-item label="归属部门"><el-select v-model="form.department"><el-option v-for="d in candidates.departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="要求完成时间"><el-date-picker v-model="form.due_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><p v-if="form.page_path">关联：{{form.record_number||form.page_path}}</p><ScreenshotEditor ref="editor" v-if="!hideCapture && rule?.screenshot_enabled!==false" @confirmed="screenshot=$event"/><label>附件 <input type="file" multiple @change="files=[...$event.target.files]"/></label><el-button native-type="submit" type="primary" :loading="busy">发起跟踪</el-button></el-form></template>
<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { tracking } from '../../api/issueTracking';
import ScreenshotEditor from './ScreenshotEditor.vue';
const props=defineProps({context:{type:Object,default:()=>({})},candidates:{type:Object,required:true},initialDescription:{type:String,default:''},initialScreenshot:{default:null},hideCapture:{type:Boolean,default:false}}),emit=defineEmits(['created']);
const editor=ref(null);
const form=reactive({title:'',description:props.initialDescription,assignee:null,collaborators:[],department:null,due_at:'',menu_key:'',page_path:'',record_type:'',record_id:'',record_number:''}),error=ref(''),busy=ref(false),screenshot=ref(props.initialScreenshot),files=ref([]),createdIssue=ref(null);
watch(()=>props.initialDescription,value=>{if(!createdIssue.value)form.description=value;});
watch(()=>props.initialScreenshot,value=>{if(!createdIssue.value)screenshot.value=value;});
defineExpose({busy,hasSavedIssue:computed(()=>Boolean(createdIssue.value))});
const candidateUsers=computed(()=>props.candidates.users.filter(u=>!rule.value?.candidate_departments?.length||u.department_ids?.some(id=>rule.value.candidate_departments.includes(id))));
const rule=computed(()=>props.candidates.rules?.find(r=>r.menu_key===form.menu_key));
watch(()=>props.context,c=>{Object.assign(form,{menu_key:'',page_path:'',record_type:'',record_id:'',record_number:''},c);if(rule.value){form.assignee=rule.value.default_assignee;form.due_at=new Date(Date.now()+rule.value.default_due_hours*3600000).toISOString();}},{immediate:true,deep:true});
watch(rule,r=>{if(r){if(!form.assignee)form.assignee=r.default_assignee;if(!form.due_at)form.due_at=new Date(Date.now()+r.default_due_hours*3600000).toISOString();}},{immediate:true});
watch(()=>form.assignee,id=>{const ds=props.candidates.users.find(u=>u.id===id)?.department_ids||[];if(!form.department&&ds.length===1)form.department=ds[0];});
async function save(){error.value='';if(editor.value?.hasUnconfirmed){error.value='请先确认截图或移除截图';return;}if(!form.title.trim()||!form.assignee||!form.department||!form.due_at){error.value='请填写标题、主处理人、归属部门和要求完成时间';return;}busy.value=true;try{createdIssue.value ||= await tracking('issues/','post',{...form});for(const file of [...files.value,...(screenshot.value?[screenshot.value]:[])]){const data=new FormData();data.append('file',file);await tracking(`issues/${createdIssue.value.id}/attachments/`,'post',data);if(file===screenshot.value)screenshot.value=null;else files.value=files.value.filter(f=>f!==file);}emit('created',createdIssue.value);}catch(e){error.value=createdIssue.value?`事项已创建，附件上传失败；重试将继续上传：${e.message}`:e.message;}finally{busy.value=false;}}
</script>
